s, st = cen.req('/api/central/state'); tp = next(t for t in st['tenants'] if t['id'] == TID); check(tp['stats']['rocas'] == 2 and tp['stats']['lancamentos'] >= 8, 'Central mostra roças e lançamentos da empresa rural')

